            delegated = true
            logcat(LogPriority.WARN, e) { "Edge TTS failed; using system voice" }
            withContext(Dispatchers.Main) { speakSystem(context, text, gender, speakerSlot) }
        } finally {
            if (!delegated) setSpeaking(false)
