metadata.preview:
 *  • пол тот же и реплика длинная → почти наверняка вторая реплика
 *    другого персонажа того же пола, поэтому чередуем двух последних.
 *
 * Монолог (длинные реплики одного персонажа подряд без смены пола)
 * получит чередование голоса, но короткие реплики и реплики с подписью
 * по-прежнему держат один голос.
 */
private fun openTurnSpeaker(gender: String, fingerprint: String): TrackedSpeaker? {
    val sameGender = trackedSpeakers.filter { it.gender == gender }
    if (sameGender.isEmpty()) return null
    val mostRecent = sameGender.last()
    // Пол сменился — возвращаемся к тому, кто уже звучал.
    if (lastSpokenGender != gender) return mostRecent
    // Тот же пол. Короткая реплика — это продолжение того же голоса.
    if (fingerprint.length < MIN_FINGERPRINT) return mostRecent
    // Длинная реплика того же пола: если есть ещё один персонаж этого
    // пола, диалог идёт между ними — отвечаем вторым.
    return sameGender.getOrNull(sameGender.size - 2) ?: mostRecent
}

display.text:
