private fun pageBox(box: OcrBoundingBox): OcrBoundingBox {
        val crop = frameGeometry?.crop ?: return box
        val w = crop.right - crop.left
        val h = crop.bottom - crop.top
        if (w <= 0f || h <= 0f) return box
        return OcrBoundingBox(
            left = crop.left + box.left * w,
            top = crop.top + box.top * h,
            right = crop.left + box.right * w,
            bottom = crop.top + box.bottom * h,
        )
    }

internal fun continueSpeakerIndex(
            sameGenderCount: Int,
            genderJustChanged: Boolean,
            longLine: Boolean,
        ): Int = when {
            sameGenderCount <= 0 -> -1
            genderJustChanged || !longLine -> sameGenderCount - 1
            sameGenderCount >= 2 -> sameGenderCount - 2
            else -> 0
        }

