+                var inStr = false
+                var i = start
+                while (i < text.length) {
+                    val c = text[i]
+                    if (inStr) {
+                        if (c == '\\') { i += 2; continue }
+                        if (c == '"') inStr = false
+                    } else {
+                        when (c) {
+                            '"' -> inStr = true
+                            '[' -> depth++
+                            ']' -> {
