                var inStr = false
                var i = start
                while (i < text.length) {
                    val c = text[i]
                    if (inStr) {
                        if (c == '\\\\') { i += 2; continue }
                        if (c == '"') inStr = false
                    } else {
                        when (c) {
                            '"' -> inStr = true
                            '[' -> depth++
                            ']' -> {
                                depth--
                                if (depth == 0) return i
                            }
                        }
                    }
                    i++
                }
                -1
            }
            '"' -> {
                var i = start + 1
                while (i < text.length) {
                    val c = text[i]
                    if (c == '\\\\') { i += 2; continue }
                    if (c == '"') return i
                    i++
                }
                -1
            }
            else -> {
                var i = start
                while (i < text.length && text[i] != ',' && !text[i].isWhitespace()) i++
                if (i == start) -1 else i - 1
            }
        }
    }

