    fun planAiVoice(
        targetEngine: String,
        aiVoice: String?,
        installedSystemVoices: Collection<String>,
        online: Boolean,
        aiAvailable: Boolean,
        fallbackOnlineEngine: String = TtsSpeaker.ENGINE_EDGE_TTS,
